#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str


def solve(S: str):
    flag = True
    strings_odd = ['R', 'U', 'D']
    strings_even = ['L', 'U', 'D']
    for i, s in enumerate(S):
        i = i + 1
        if i % 2 == 0:
            if s in strings_even:
                pass
            else:
                flag = False
        if i % 2 == 1:
            if s in strings_odd:
                pass
            else:
                flag = False
    if flag == True:
        print('Yes')
    else:
        print('No')
    return


# Generated by 1.1.5 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

if __name__ == '__main__':
    main()
